package springboot_based.ams.exception;import org.springframework.http.HttpStatus;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.ExceptionHandler;import org.springframework.web.bind.annotation.RestControllerAdvice;import java.util.HashMap;import java.util.Map;@RestControllerAdvicepublic class GlobalExceptionHandler {    @ExceptionHandler(Exception.class)    public ResponseEntity<Map<String, String>> handleGenericException(Exception ex) {        Map<String, String> error = new HashMap<>();        error.put("error", ex.getClass().getSimpleName());        error.put("message", ex.getMessage() != null ? ex.getMessage() : "Unknown error");        ex.printStackTrace();        return new ResponseEntity<>(error, HttpStatus.INTERNAL_SERVER_ERROR);    }    @ExceptionHandler(ResourceNotFoundException.class)    public ResponseEntity<Map<String, String>> handleNotFound(ResourceNotFoundException ex) {        Map<String, String> error = new HashMap<>();        error.put("error", "Not Found");        error.put("message", ex.getMessage());        return new ResponseEntity<>(error, HttpStatus.NOT_FOUND);    }}